</script>

<template>
  <section id="stack" class="px-6 md:px-12 lg:px-24 mb-40 fade-in-up">
    <div class="max-w-7xl mx-auto">
      <div class="mb-16">
        <p class="text-xs uppercase tracking-[0.3em] text-secondary mb-4">
          {{ t('stack.tagline') }}
        </p>
        <h2 class="text-4xl md:text-6xl font-serif">
          <span class="highlight-offset-md">{{ t('stack.title') }}</span>
        </h2>
      </div>

      <div class="grid justify-items-center grid-cols-3 md:grid-cols-6 gap-x-12 gap-y-10">
        <div
          v-for="tech in technologies"
          :key="tech.name"
          class="flex flex-col items-center gap-3 cursor-default"
          @mouseenter="hovered = tech.name"
          @mouseleave="hovered = null"
        >
          <div
            aria-hidden="true"
            class="tech-icon w-10 h-10 md:w-12 md:h-12 transition-opacity duration-300"
            :class="hovered === tech.name ? 'opacity-100' : 'opacity-90'"
            v-html="hovered === tech.name ? tech.svg : gray(tech.svg)"
          />
          <span
            class="text-xs uppercase tracking-[0.15em] transition-colors duration-300"
            :class="hovered === tech.name ? 'text-charcoal' : 'text-secondary'"
          >
            {{ tech.name }}
          </span>
        </div>
      </div>
    </div>
  </section>
</template>

<style scoped>
.tech-icon {
  color: #6e6e6e;
}

.tech-icon :deep(svg) {
  /* height was 1lh, which resolved to the 24px line-height: the svg box came
     out 40x24 while its viewBox is square, so the glyph met the smaller side
     and drew at 24px inside a 40px container. Filling the box squares it. */
  width: 100%;
  height: 100%;
}

.highlight-offset-md {
  position: relative;
  display: inline-block;
  z-index: 1;
}
.highlight-offset-md::before {
  /* lh, not %: a percentage is a share of the whole box, so a heading that
     wrapped to two lines got a bar 48px tall against a 40px line and swallowed
     the second one. One line's worth, however many lines there are. */
  content: '';
  display: block;
  width: calc(100% - 30px);
  height: 0.6lh;
  position: absolute;
  bottom: -10px;
  left: 30px;
  z-index: -1;
  background-color: var(--lavender);
  transition: all 0.3s ease;
}
.highlight-offset-md:hover::before {
  height: 0.4lh;
}
